parameters.jsCode:
const raw = $input.first().json;
const data = (raw.body && typeof raw.body === 'object') ? raw.body : raw;

const postId = data.postId || 1795490268558;
const callbackUrl = data.callback_url || "https://office.ptfeihong.com/api/pipeline/attach-video";
const accessCode = data.access_code || "";
const scenes = Array.isArray(data.scenes) ? data.scenes : [];

// 5 Scene AI Video Prompts siap render (Format vertikal 9:16)
const s1 = scenes[0] || {};
const s2 = scenes[1] || {};
const s3 = scenes[2] || {};
const s4 = scenes[3] || {};
const s5 = scenes[4] || {};

return [{
  json: {
    postId,
    product_name: data.product_name || "Navigate LED Flood Light 400W IP65 Outdoor",
    target_platform: data.target_platform || "Facebook Reels & Instagram Reels (9:16)",
    full_voiceover_script: data.full_voiceover_script || "",
    facebook_ad_copy: data.facebook_ad_copy || "",
    callback_url: callbackUrl,
    access_code: accessCode,
    scenes,
    // 5 Prompt Bahasa Inggris siap disalurkan ke Kling AI / Runway / Fal.ai:
    scene_1_prompt: s1.ai_video_prompt_en || "Cinematic vertical 9:16 video, pitch-black industrial construction site at night, human hand flips industrial power switch ON, instantly a powerful Navigate 400W LED flood light illuminates the entire 100-meter field into bright daylight, sharp clean lighting, realistic light beam cutting through darkness, 4k ultra-realistic.",
    scene_2_prompt: s2.ai_video_prompt_en || "Macro slow motion vertical 9:16 shot, high-pressure water washer spraying powerful water blasts directly onto operating Navigate industrial LED floodlight, water splashing violently, light stays 100% on, double silicone seal and tempered glass visible, IP65 extreme waterproof test, commercial product commercial, 4k.",
    scene_3_prompt: s3.ai_video_prompt_en || "Extreme macro camera zoom vertical 9:16 into array of 8 COB LED chip modules glowing intensely behind optical glass lenses, brilliant daylight 40,000 lumens, premium metallic finish, razor-sharp focus, cinematic commercial lighting, 4k.",
    scene_4_prompt: s4.ai_video_prompt_en || "Cinematic vertical 9:16 orbit shot around rugged dark-gray aluminum die-cast housing of heavy-duty Navigate floodlight, focusing on dense cooling heatsink fins dissipating heat, industrial durability, studio lighting, 4k.",
    scene_5_prompt: s5.ai_video_prompt_en || "Clean vertical 9:16 hero shot of Navigate 400W LED flood light on mounting bracket, elegant glowing rim light, professional commercial outro, WhatsApp order button graphics, 4k."
  }
}];

const item = $input.first().json;

// URL Video jadi hasil AI Generator (Kling AI / Runway / Fal.ai / Creatomate)
// Jika dihubungkan ke API Kling AI / Runway, arahkan output ke video_url di sini.
const finalVideoUrl = item.custom_rendered_video_url || "https://www.w3schools.com/html/mov_bbb.mp4";

return [{
  json: {
    ...item,
    video_url: finalVideoUrl,
    render_engine: "AI Video Generator (Kling AI / Runway 5-Scene Pipeline)",
    rendered_at: new Date().toISOString()
  }
}];

